design.css:
/* Original retro adventure menu styling. Colors remain editable in Visual. */
:scope {
  --tigrana-panel-gap: 20px;
  --tigrana-workspace-inset: 18px;
  --tigrana-panel-radius: 0px;
  --tigrana-panel-shadow: 0 0 0 2px #080e09, inset 0 0 0 1px var(--tigrana-text), 5px 5px 0 #00000080;
}
.app-titlebar { background: var(--surface); border-bottom: 3px solid var(--tigrana-accent); }
.note-tab { border-radius: 0; font-weight: 400; }
.note-tab.is-active { background: var(--tigrana-accent); color: var(--tigrana-selected-text); box-shadow: inset 0 0 0 1px var(--tigrana-text); }
.folder-pane, .notes-pane, .unified-tree-pane, .main-pane, .right-sidebar { border: 3px solid var(--tigrana-accent); }
.folder-pane, .notes-pane, .unified-tree-pane, .main-pane, .right-sidebar { border-width: calc(var(--tigrana-control-border-width, 3) * 1px); }
.right-sidebar { border-color: var(--tigrana-highlight-background); }
.pane-header { padding: 12px; font-size: 20px; text-transform: uppercase; font-weight: 400; letter-spacing: 0.04em; background: transparent; border-bottom: 1px solid var(--tigrana-border); }
.topbar { border-bottom: 1px solid var(--tigrana-border); }
.toolbar-button, .icon-button { border-radius: 0; }
.folder-row, .note-row, .unified-tree-row { border-radius: 0; }
.section-view-folder-pane .folder-row { margin-right: 6px; }
.title-shell { margin-top: 16px; margin-bottom: 0; padding-bottom: 12px; }
.editor-shell { padding-top: 16px; }
.note-title-input { margin: 0; padding: 0; font-weight: 400; text-transform: uppercase; letter-spacing: 0.04em; }
.ProseMirror h1, .ProseMirror h2, .ProseMirror h3 { color: var(--tigrana-accent); font-weight: 400; text-transform: uppercase; letter-spacing: 0.04em; }
/* Keep even the smallest heading visibly larger than body text. */
.ProseMirror h6 { font-size: calc(var(--editor-font-size) * 1.1); }
.ProseMirror a { color: var(--tigrana-accent); text-decoration-style: dotted; text-underline-offset: 4px; }
:scope.theme-dark .ProseMirror a { color: var(--tigrana-highlight-background); }
.ProseMirror blockquote { background: var(--surface-soft); border: 3px double var(--tigrana-accent); padding: 12px 16px; }
.ProseMirror pre, .ProseMirror table { border: 3px double var(--tigrana-border); border-radius: 0; }
.ProseMirror code, .ProseMirror pre { font-family: var(--editor-font-family); }
.ProseMirror hr { border-top: 3px double var(--tigrana-border); }
.pane-resizer { background: transparent; }
.pane-resizer::after { opacity: 0; }
.pane-resizer:hover::after, .pane-resizer:focus-visible::after { opacity: 1; }
.topbar-note-title { font-weight: 400; }

/* Keep the pixel font readable in the editor options menu. */
.note-view-dropdown strong { font-weight: 400; }
.note-view-dropdown small { white-space: normal; }
.note-view-menu-label { font-weight: 400; }

/* Keep nested outline headings readable with the pixel font. */
.outline-item.level-3, .outline-item.level-4, .outline-item.level-5, .outline-item.level-6 { font-size: max(18px, calc(var(--tigrana-font-navigation) * 0.9)); }
